window.WORD_VOICE_PAGES = {"f-v01":{"word":"予定","reading":"よてい","pageUrl":"https://forvo.com/word/予定/#ja","verified":true},"f-v02":{"word":"約束","reading":"やくそく","pageUrl":"https://forvo.com/word/約束/#ja","verified":true},"f-v03":{"word":"間に合う","reading":"まにあう","pageUrl":"https://forvo.com/word/間に合う/#ja","verified":true},"f-v04":{"word":"準備","reading":"じゅんび","pageUrl":"https://forvo.com/word/準備/#ja","verified":true},"f-v05":{"word":"続ける","reading":"つづける","pageUrl":"https://ja.forvo.com/word/続ける/#ja","verified":true},"f-v06":{"word":"比べる","reading":"くらべる","pageUrl":"https://forvo.com/word/比べる/#ja","verified":false},"f-v07":{"word":"確かめる","reading":"たしかめる","pageUrl":"https://forvo.com/word/確かめる/#ja","verified":true},"f-v08":{"word":"必要","reading":"ひつよう","pageUrl":"https://forvo.com/word/必要/#ja","verified":true},"f-v09":{"word":"慣れる","reading":"なれる","pageUrl":"https://ru.forvo.com/word/慣れる/#ja","verified":true},"f-v10":{"word":"途中","reading":"とちゅう","pageUrl":"https://ja.forvo.com/word/途中/#ja","verified":true},"f-v11":{"word":"原因","reading":"げんいん","pageUrl":"https://forvo.com/word/原因/#ja","verified":true},"f-v12":{"word":"復習","reading":"ふくしゅう","pageUrl":"https://forvo.com/word/復習/#ja","verified":true},"n-v01":{"word":"改善","reading":"かいぜん","pageUrl":"https://forvo.com/word/%E6%94%B9%E5%96%84/#ja","verified":true},"n-v02":{"word":"維持","reading":"いじ","pageUrl":"https://ja.forvo.com/word/%E7%B6%AD%E6%8C%81/#ja","verified":true},"n-v03":{"word":"傾向","reading":"けいこう","pageUrl":"https://ja.forvo.com/word/%E5%82%BE%E5%90%91/#ja","verified":false},"n-v04":{"word":"影響","reading":"えいきょう","pageUrl":"https://forvo.com/word/%E5%BD%B1%E9%9F%BF/#ja","verified":true},"n-v05":{"word":"対応","reading":"たいおう","pageUrl":"https://ja.forvo.com/word/%E5%AF%BE%E5%BF%9C/#ja","verified":false},"n-v06":{"word":"判断","reading":"はんだん","pageUrl":"https://forvo.com/word/%E5%88%A4%E6%96%AD/#ja","verified":true},"n-v07":{"word":"効率","reading":"こうりつ","pageUrl":"https://ja.forvo.com/word/%E5%8A%B9%E7%8E%87/#ja","verified":false},"n-v08":{"word":"実施","reading":"じっし","pageUrl":"https://ja.forvo.com/word/%E5%AE%9F%E6%96%BD/#ja","verified":false},"n-v09":{"word":"調整","reading":"ちょうせい","pageUrl":"https://ja.forvo.com/word/%E8%AA%BF%E6%95%B4/#ja","verified":false},"n-v10":{"word":"取り組む","reading":"とりくむ","pageUrl":"https://ja.forvo.com/word/%E5%8F%96%E3%82%8A%E7%B5%84%E3%82%80/#ja","verified":false},"n-v11":{"word":"見直す","reading":"みなおす","pageUrl":"https://ja.forvo.com/word/%E8%A6%8B%E7%9B%B4%E3%81%99/#ja","verified":true},"n-v12":{"word":"応用","reading":"おうよう","pageUrl":"https://ja.forvo.com/word/%E5%BF%9C%E7%94%A8/#ja","verified":false}};
const localWordAudioCache=new Map();
const localWordAudioIds=new Set();
let localWordAudioDb=null,activeWordAudio=null,activeWordAudioUrl=null,wordAudioRequest=0;
function stopWordAudio(){wordAudioRequest++;if('speechSynthesis'in window)window.speechSynthesis.cancel();if(activeWordAudio){activeWordAudio.pause();activeWordAudio.src='';activeWordAudio=null;}if(activeWordAudioUrl){URL.revokeObjectURL(activeWordAudioUrl);activeWordAudioUrl=null;}}
function hasWordRecording(id){return localWordAudioIds.has(id);}
function bundledWordRecording(v){const clip=window.BUNDLED_WORD_AUDIO?.[v.id];return clip&&clip.word===v.word&&clip.reading===v.reading?clip:null;}
function wordAudioButtonLabel(v){return hasWordRecording(v.id)?'▷ 播放本地音频':bundledWordRecording(v)?'▷ 播放真人录音':'▷ 设备朗读';}
function wordVoiceLinks(v){const clip=bundledWordRecording(v),source=window.WORD_VOICE_PAGES[v.id];const page=source?.pageUrl||`https://forvo.com/word/${encodeURIComponent(v.word)}/#ja`;return `<div class="button-row section-gap" style="justify-content:center"><button class="button ghost" data-action="attach-word-audio" data-id="${esc(v.id)}">${hasWordRecording(v.id)?'更换本地音频':'＋ 导入自己的读音'}</button>${clip?'':`<a class="button secondary" href="${esc(page)}" target="_blank" rel="noopener">查找真人发音 ↗</a>`}</div><p class="panel-note">${hasWordRecording(v.id)?'使用你导入的本地音频。':clip?`已内置日本母语者录音，可离线播放。<a href="${esc(clip.sourcePage)}" target="_blank" rel="noopener">录音来源 ↗</a>`:'这个词尚未内置真人录音，当前使用设备合成语音。'}</p>`;}
async function openWordAudioDb(){if(localWordAudioDb)return localWordAudioDb;if(!('indexedDB'in window))throw Error('浏览器不支持音频持久存储');return new Promise((resolve,reject)=>{const request=window.indexedDB.open('nichinichi-word-audio',1);request.onupgradeneeded=()=>{if(!request.result.objectStoreNames.contains('clips'))request.result.createObjectStore('clips',{keyPath:'id'});};request.onerror=()=>reject(Error('本地音频存储不可用'));request.onsuccess=()=>{localWordAudioDb=request.result;localWordAudioDb.onversionchange=()=>{localWordAudioDb.close();localWordAudioDb=null;};resolve(localWordAudioDb);};});}
async function loadWordRecording(id){if(localWordAudioCache.has(id))return localWordAudioCache.get(id);if(!hasWordRecording(id))return null;const db=await openWordAudioDb();return new Promise((resolve,reject)=>{const request=db.transaction('clips','readonly').objectStore('clips').get(id);request.onsuccess=()=>{if(request.result)localWordAudioCache.set(id,request.result);resolve(request.result||null);};request.onerror=()=>reject(Error('音频读取失败'));});}
async function saveWordRecording(id,file){if(file.size>10*1024*1024)throw Error('词条音频请控制在10MB以内，整章音频请用普通播放器播放');if(!file.size)throw Error('音频文件为空');if(!(file.type.startsWith('audio/')||/\.(mp3|m4a|wav|ogg|oga|opus|aac|flac)$/i.test(file.name)))throw Error('请选择音频文件');const record={id,name:file.name,blob:file};const db=await openWordAudioDb();await new Promise((resolve,reject)=>{const tx=db.transaction('clips','readwrite');tx.objectStore('clips').put(record);tx.oncomplete=resolve;tx.onerror=()=>reject(Error('音频保存失败，请检查浏览器存储空间'));tx.onabort=()=>reject(Error('音频保存被浏览器中止'));});localWordAudioCache.set(id,record);localWordAudioIds.add(id);}
async function playWordAudio(v,{requireRecording=false}={}){stopWordAudio();const token=wordAudioRequest;try{const record=await loadWordRecording(v.id);if(token!==wordAudioRequest)return;const clip=bundledWordRecording(v);if(!record&&!clip){if(requireRecording){toast("这个词的录音已不可用，请重新导入或开始下一轮。");return;}speak(v.reading||v.word);return;}if('speechSynthesis'in window)window.speechSynthesis.cancel();if(record)activeWordAudioUrl=URL.createObjectURL(record.blob);const player=new Audio(record?activeWordAudioUrl:clip.dataUrl);activeWordAudio=player;player.onended=()=>{if(token===wordAudioRequest)stopWordAudio();};player.onerror=()=>{if(token===wordAudioRequest){stopWordAudio();toast('该音频未能播放，请检查浏览器支持的音频格式。');}};await player.play();}catch(e){if(token===wordAudioRequest){stopWordAudio();toast(e.message||'音频播放未成功，请再点一次播放。');}}}
function attachWordAudio(id){const v=vocab().find(x=>x.id===id);if(!v)return;modal('给「'+esc(v.word)+'」导入读音',`<p class="subtext">选择你已取得的该单词音频。保存后词卡可以直接播放；请先确认音频里的词和假名读音「${esc(v.reading)}」一致。</p><label class="button secondary full" for="word-audio-file">选择词条音频文件</label><input id="word-audio-file" type="file" accept="audio/*,.mp3,.m4a,.wav,.ogg,.oga,.opus,.aac,.flac" data-word-id="${esc(id)}" class="visually-hidden"><p class="panel-note">每个词条最多10MB。词条音频保存在当前浏览器，不包含在学习记录JSON备份中；请保留原始音频文件。</p>${hasWordRecording(id)?`<button class="text-link danger section-gap" data-action="remove-word-audio" data-id="${esc(id)}">移除这个词的本地音频</button>`:''}`);}
async function removeWordRecording(id){stopWordAudio();const db=await openWordAudioDb();await new Promise((resolve,reject)=>{const tx=db.transaction('clips','readwrite');tx.objectStore('clips').delete(id);tx.oncomplete=resolve;tx.onerror=()=>reject(Error('移除失败'));});localWordAudioCache.delete(id);localWordAudioIds.delete(id);}
function wordAudioCredit(){return `<p class="panel-note">录音来自 <a href="https://www.tofugu.com" target="_blank" rel="noopener">Tofugu</a> / <a href="https://www.wanikani.com" target="_blank" rel="noopener">WaniKani</a>（<a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noopener">CC BY-SA 4.0</a>）及 <a href="https://kanjialive.com" target="_blank" rel="noopener">Kanji alive</a>（<a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener">CC BY 4.0</a>）。只按词条选取、打包，未改动录音。Tofugu 库混合东京男声与关西女声；逐条说话人未标注。</p>`;}

function officialWordAudioSourcesCard(){return `<section class="card"><span class="pill">教材与词音资源</span><h2 class="section-gap">官方单词学习音频</h2><h3>先补基础 · IRODORI 词汇录音</h3><p class="subtext">国际交流基金提供入门、初级1、初级2的词表和MP3。录音按课、词组顺序朗读，适合对照词表跟读。你先从初级1选不熟的词，入门部分按需补漏。</p><div class="button-row"><a class="button secondary" href="https://www.irodori.jpf.go.jp/wordlists/audio/elementary01_01.html" target="_blank" rel="noopener">初级1 · 官方播放 ↗</a><a class="button ghost" href="https://www.irodori.jpf.go.jp/resources.html" target="_blank" rel="noopener">三套词表与下载 ↗</a></div><h3 class="section-gap">进入 N2 · ASK 单词 2500</h3><p class="subtext">ASK 出版社《はじめての日本語能力試験 N2単語2500》提供单词与例句录音；官方教材页可在线播放，也有ZIP下载与手机播放渠道。音频公开提供，教材正文另需合法取得。</p><a class="button ghost full" href="https://ask-books.com/book-details/?slug=9784872179842" target="_blank" rel="noopener">N2 单词 2500 · 官方音频入口 ↗</a><h3 class="section-gap">检查重音与变形 · OJAD</h3><p class="subtext">东京大学等参与开发的日语声调辞典。单词搜索中的男声、女声是专业声优录音，可学习动词各活用形；电脑上 Shift＋点击录音按钮可下载MP3。</p><a class="button ghost full" href="https://www.gavo.t.u-tokyo.ac.jp/ojad/zho/pages/home" target="_blank" rel="noopener">OJAD 中文界面 ↗</a><p class="panel-note">外部资源的可用性与使用条款以相应机构网站为准，本站仅提供入口，不包含这些教材的整套下载包。本站内置的${Object.keys(window.BUNDLED_WORD_AUDIO||{}).length}条逐词音频可以离线播放。</p></section>`;}
function wordAudioResourceCard(){const words=window.STUDY_DATA.vocabulary;return `<section class="card"><h2>词条真人读音</h2><div class="metric-grid">${Object.entries(VOCAB_STAGES).map(([stage,title])=>{const items=words.filter(v=>vocabStage(v)===stage);return `<div class="metric"><strong>${items.filter(v=>bundledWordRecording(v)).length}<span class="audio-total"> / ${items.length}</span></strong><small>${title}已配音</small></div>`;}).join('')}</div><p class="subtext section-gap">内置真人录音可离线播放，缺少录音的词标为「设备朗读」。听写练习只使用有录音的词。</p><button class="button secondary full" data-action="word-audio-library">查词、看搭配、听读音</button>${wordAudioCredit()}</section>${officialWordAudioSourcesCard()}`;}
function wordAudioLibrary(){openVocabularyLibrary();}

document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;if(['rate','study-tab','start-today','today','plan','diagnostic','close-modal'].includes(el.dataset.action))stopWordAudio();if(el.dataset.action==='word-audio-library')wordAudioLibrary();if(el.dataset.action==='attach-word-audio')attachWordAudio(el.dataset.id);if(el.dataset.action==='remove-word-audio'){try{await removeWordRecording(el.dataset.id);$('#modal').close();render();toast('本地音频已移除。');}catch(err){toast(err.message);}}});
document.addEventListener('change',async e=>{if(e.target.id!=='word-audio-file'){if(e.target.matches?.('select'))stopWordAudio();return;}const file=e.target.files[0],id=e.target.dataset.wordId;if(!file)return;try{await saveWordRecording(id,file);$('#modal').close();render();toast('词条音频已保存，可以离线播放。');}catch(err){toast(err.message);}});
window.addEventListener('pagehide',()=>stopWordAudio());
document.querySelector('#modal')?.addEventListener?.('cancel',()=>stopWordAudio());
document.querySelector('#modal')?.addEventListener?.('close',()=>stopWordAudio());
if('indexedDB'in window)openWordAudioDb().then(db=>new Promise((resolve,reject)=>{const request=db.transaction('clips','readonly').objectStore('clips').getAllKeys();request.onsuccess=()=>resolve(request.result);request.onerror=reject;})).then(ids=>{ids.forEach(id=>localWordAudioIds.add(id));if(typeof render==='function'&&ids.length)render();}).catch(()=>{});
